mapper.select:
select id, shop_code, logcode as log_code, productioncode as production_code, operation,
       doccode as doc_code, doctype as doc_type, docdetailcode as doc_detail_code,
       goodscode as goods_code, qty, costamount as cost_amount,
       operationtime as operation_time, remark
  from sdsorder.u_f_productionlog_${tableSuffix}
 where shop_code = #{shopCode}
and productioncode = #{productionCode}
and operation = #{operation}
 order by operationtime desc, id desc
